// @vitest-environment node
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

// The home-screen, manifest and favicon files are generated by
// scripts/icons.mjs from src/assets/brand/favicon.svg; rerun it after changing
// the master. tests/crew_browser.mjs checks that the server serves them.
const ui = fileURLToPath(new URL("..", import.meta.url));
const read = (path: string) => readFileSync(`${ui}${path}`);
const generated = ["apple-touch-icon.png", "favicon.ico", "icon-192.png", "icon-512.png", "icon-maskable-512.png"];

function pngInfo(data: Buffer) {
  expect(data.subarray(0, 8)).toEqual(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
  expect(data.toString("ascii", 12, 16)).toBe("IHDR");
  return { width: data.readUInt32BE(16), height: data.readUInt32BE(20), colorType: data[25] };
}

describe("reader icons", () => {
  const hash = createHash("sha256");
  for (const name of generated) hash.update(name).update(read(`public/${name}`));
  const v = hash.digest("hex").slice(0, 10);
  const index = read("index.html").toString();
  const manifest = JSON.parse(read("public/manifest.webmanifest").toString());

  it("links every icon and the manifest with the current content version", () => {
    expect(index).toContain(`<link rel="apple-touch-icon" href="/apple-touch-icon.png?v=${v}" />`);
    expect(index).toContain(`<link rel="manifest" href="/manifest.webmanifest?v=${v}" />`);
    expect(index).toContain(`<link rel="icon" href="/favicon.ico?v=${v}" sizes="32x32" />`);
    expect(index).toContain(`<link rel="icon" type="image/svg+xml" href="/src/assets/brand/favicon.svg" />`);
    expect(index).toContain(`<meta name="apple-mobile-web-app-title" content="Crew" />`);
    expect(index).toContain(`<meta name="application-name" content="Crew" />`);
    expect(index).toMatch(/<meta name="theme-color" content="#[0-9a-f]{6}" \/>/);
  });

  it("describes Crew in the manifest", () => {
    expect(manifest).toMatchObject({
      name: "Crew",
      short_name: "Crew",
      start_url: "/",
      display: "standalone",
      theme_color: "#0d1712",
      background_color: "#0d1712",
    });
    expect(manifest.icons).toEqual([
      { src: `/icon-192.png?v=${v}`, sizes: "192x192", type: "image/png", purpose: "any" },
      { src: `/icon-512.png?v=${v}`, sizes: "512x512", type: "image/png", purpose: "any" },
      { src: `/icon-maskable-512.png?v=${v}`, sizes: "512x512", type: "image/png", purpose: "maskable" },
    ]);
  });

  it("ships opaque PNGs of the declared sizes", () => {
    for (const [name, size] of [
      ["apple-touch-icon.png", 180],
      ["icon-192.png", 192],
      ["icon-512.png", 512],
      ["icon-maskable-512.png", 512],
    ] as const) {
      // Colour type 2 is RGB without alpha: iOS fills transparency with black.
      expect({ name, ...pngInfo(read(`public/${name}`)) }).toEqual({ name, width: size, height: size, colorType: 2 });
    }
  });

  it("ships a 32×32 ICO with an embedded PNG", () => {
    const ico = read("public/favicon.ico");
    expect([ico.readUInt16LE(0), ico.readUInt16LE(2), ico.readUInt16LE(4), ico[6], ico[7]]).toEqual([0, 1, 1, 32, 32]);
    const offset = ico.readUInt32LE(18);
    expect(ico.readUInt32LE(14)).toBe(ico.length - offset);
    expect(pngInfo(ico.subarray(offset))).toMatchObject({ width: 32, height: 32 });
  });
});
